#Requires -Version 7.0
[CmdletBinding()]param([Parameter(Mandatory)][string]$Story,[Parameter(Mandatory)][string]$PromotionDate,[string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../../..'))}
$integrity=Join-Path $ProjectRoot '.agents/skills/story-integrity/scripts';. (Join-Path $integrity 'PipelineCommon.ps1');. (Join-Path $integrity 'PipelineTransactions.ps1');. (Join-Path $integrity 'PromotionContracts.ps1');Assert-ProductionBranch $ProjectRoot
$dir=Join-Path $ProjectRoot "stories/$Story";$promotionPath=Join-Path $dir 'promotion.json';$p=Read-PipelineJson $promotionPath;Assert-PromotionRecord $p $Story;if($p.state-cne'ready'-or$p.promotionDate-cne$PromotionDate){throw 'Promotion is not ready for the requested date.'};if(@($p.deltaDispositions|Where-Object disposition -ne 'promote').Count){throw 'This promotion was authorized to promote every delta item; non-promote dispositions remain.'};$record=Read-PipelineJson(Join-Path $dir 'story.json');if($record.status-cne'candidate'-or$record.provenance-cne'pipeline'){throw 'Standard promotion requires a pipeline candidate.'}
$paths=@("stories/$Story/story.json","stories/$Story/README.md","stories/$Story/release.json","stories/$Story/promotion.json","stories/$Story/authority.json",'stories/INDEX.md','stories/NAMES.md')+@($p.modifiedFiles)
try{Invoke-PipelineTransaction -ProjectRoot $ProjectRoot -Path $paths -Mutation {$record.stage='final';$record.status='final';$record.canon=$true;$record.userDisposition='accepted';$record.promotionDate=$PromotionDate;Write-PipelineJson(Join-Path $dir 'story.json')$record;Set-StoryReadmeProjection(Join-Path $dir 'README.md')$record;Set-StoryIndexProjection(Join-Path $ProjectRoot 'stories/INDEX.md')$record 'Canon promotion completed.';Set-StoryRegistryState(Join-Path $ProjectRoot 'stories/NAMES.md')$Story 'canon' '';$p.state='completed';$p.completedAt=[DateTimeOffset]::UtcNow.ToString('o');$p.result='PROMOTED';$p.rollback.attempted=$false;$p.rollback.succeeded=$null;$p.rollback.detail=$null;Write-PipelineJson $promotionPath $p;& (Join-Path $integrity 'New-AuthorityManifest.ps1') -Story $Story -ProjectRoot $ProjectRoot *> $null;& (Join-Path $integrity 'New-StoryRelease.ps1') -Story $Story -ProjectRoot $ProjectRoot *> $null;& (Join-Path $integrity 'Test-StoryIntegrity.ps1') -Story $Story -OutputFormat Json -ProjectRoot $ProjectRoot *> $null;$postconditionOk=$?;if(-not$postconditionOk){throw 'Promotion postcondition failed.'}}}catch{$restored=Read-PipelineJson $promotionPath;$restored.rollback.attempted=$true;$restored.rollback.succeeded=$true;$restored.rollback.detail=$_.Exception.Message;Write-PipelineJson $promotionPath $restored;throw}
[ordered]@{schemaVersion=1;story=$Story;promotionDate=$PromotionDate;result='PROMOTED'}|ConvertTo-Json